<script lang="ts">
  import { onDestroy } from 'svelte';
  import { buildPalette, paletteText, contrast, type Harmony } from '$lib/utils/palette';
  import Icon from '$lib/components/Icon.svelte';
  let hue = 265;
  let harmony: Harmony = 'analogous';
  let message = '';
  let copied = '';
  let timeout: ReturnType<typeof setTimeout>;
  const harmonies: { id: Harmony; label:string; note:string }[] = [{ id:'analogous', label:'En sintonía', note:'Colores vecinos' },{ id:'complementary', label:'En contraste', note:'Opuestos que conectan' },{ id:'triadic', label:'En equilibrio', note:'Tres puntos de vista' }];
  $: palette = buildPalette(hue, harmony);
  $: css = `:root {\n${palette.map(color => `  --color-${color.key}: ${color.hex};`).join('\n')}\n}`;
  async function copy(text: string, label:string) {
    try { await navigator.clipboard.writeText(text); message = `${label} copiado.`; copied = label; }
    catch { message = 'No se pudo copiar automáticamente. Selecciona el código de abajo para copiarlo.'; }
    clearTimeout(timeout); timeout = setTimeout(() => { message = ''; copied = ''; }, 3000);
  }
  onDestroy(() => clearTimeout(timeout));
</script>
<svelte:head><title>Color Studio — Johan Aristizabal</title><meta name="description" content="Explora armonías, crea una paleta y prueba sus colores en una pequeña interfaz. Copia los colores y llévatelos a tu próxima idea." /></svelte:head>
<div class="app-shell shell studio-app">
  <a class="back-link" href="/#color-studio">← Volver al laboratorio</a>
  <div class="app-heading"><div><p class="eyebrow">THE LITTLE LAB / 01</p><h1>Color <span class="serif">Studio.</span></h1><p>Un poco de color puede cambiar toda una idea.</p></div><span class="demo-badge"><span></span> EXPLORA. COMBINA. LLÉVATE ALGO.</span></div>
  <div class="studio-toolbar"><div class="hue-control"><label for="hue">Elige tu punto de partida <span>{Math.round(hue)}°</span></label><input id="hue" type="range" min="0" max="359" bind:value={hue} /></div><div class="harmony-control" aria-label="Armonía de colores">{#each harmonies as item}<button aria-pressed={harmony === item.id} class:active={harmony === item.id} on:click={() => harmony = item.id}>{item.label}<small>{item.note}</small></button>{/each}</div><button class="button outline" on:click={() => hue = Math.floor(Math.random() * 360)}>Sorpréndeme <Icon name="spark" size={17}/></button></div>
  <div class="studio-swatches">{#each palette as color, i}<button class="studio-swatch" style={`background:${color.hex};color:${paletteText(color.hex)}`} on:click={() => copy(color.hex,color.name)} aria-label={`Copiar ${color.name}: ${color.hex}`}><span class="swatch-index">0{i + 1} / {color.name}</span><span class="swatch-hex">{color.hex.toUpperCase()}<small>{copied === color.name ? '✓ Copiado' : 'Toca para copiar'}</small></span><span class="swatch-circle" aria-hidden="true"></span></button>{/each}</div>
  <div class="studio-bottom"><section class="studio-preview" style={`--preview-paper:${palette[0].hex};--preview-primary:${palette[1].hex};--preview-secondary:${palette[2].hex};--preview-accent:${palette[3].hex};--preview-ink:${palette[4].hex};--preview-button-text:${paletteText(palette[1].hex)}`}><div class="preview-top"><span>YOUR NEXT IDEA®</span><span>01 / A LITTLE PREVIEW</span></div><div class="preview-composition" aria-hidden="true"><span></span><span></span><span></span></div><div class="preview-copy"><p>BUENAS IDEAS. NUEVOS COLORES.</p><h2>Algo pequeño.<br /><span class="serif">Muchas posibilidades.</span></h2><p>Una muestra de cómo se sienten tus colores juntos.</p><button on:click={() => copy(css,'Paleta CSS')}>Llevarme esta paleta <Icon name="arrow" size={18}/></button></div><div class="preview-bottom"><span>COLOR WITH INTENTION.</span><span>Texto / fondo {contrast(palette[0].hex,palette[4].hex).toFixed(1)}:1</span></div></section><section class="studio-export panel"><p class="eyebrow">LISTA PARA TU PRÓXIMA IDEA</p><h2>Encuentra tu combinación.</h2><p>Mueve el tono, prueba una armonía y mira cómo cambia la composición. Copia un color o la paleta completa.</p><pre><code>{css}</code></pre><button class="button dark" on:click={() => copy(css,'Paleta CSS')}>{copied === 'Paleta CSS' ? '✓ Paleta copiada' : 'Copiar paleta CSS'}<Icon name="arrow" size={16}/></button><small>La tinta y el fondo se combinan para mantener el texto legible.</small></section></div>
  <p class="studio-status" role="status">{message}</p>
</div>
