70px;height:170px;right:-60px;top:45px;border:1px solid currentColor;border-radius:50%;opacity:.15;transition:transform .5s}.studio-swatch:hover .swatch-circle{transform:translate(-25px,10px) scale(1.1)}.studio-bottom{display:grid;grid-template-columns:1.4fr 1fr;gap:26px}.studio-preview{position:relative;border-radius:13px;background:var(--preview-paper);color:var(--preview-ink);padding:26px;overflow:hidden;min-height:420px;transition:background .3s,color .3s}.preview-top,.preview-bottom{display:flex;justify-content:space-between;gap:15px;font-size:8px;letter-spacing:.08em;position:relative;z-index:1}.preview-bottom{padding-top:22px;border-top:1px solid color-mix(in srgb,var(--preview-ink) 20%,transparent);margin-top:26px}.preview-copy{position:relative;z-index:1;padding-top:65px}.preview-copy>p:first-child{font-size:8px;letter-spacing:.1em;margin-bottom:15px}.preview-copy h2{font-size:clamp(28px,3.3vw,45px);line-height:1.12;max-width:390px}.preview-copy>p:not(:first-child){font-size:11px;line-height:1.8;margin:17px 0;max-width:210px}.preview-copy button{display:flex;align-items:center;gap:15px;background:var(--preview-primary);color:var(--preview-button-text);border:0;padding:13px 17px;border-radius:30px;min-height:44px;font-size:11px}.preview-composition{position:absolute;right:-10px;top:45px;width:235px;height:280px;opacity:.85}.preview-composition span{position:absolute;width:150px;height:150px;border-radius:50%;background:var(--preview-primary);right:-5px;top:0}.preview-composition span:nth-child(2){background:var(--preview-secondary);top:80px;right:65px;border-radius:100px 100px 0 100px;transform:rotate(-20deg)}.preview-composition span:nth-child(3){background:var(--preview-accent);width:95px;height:95px;top:180px;right:5px;border-radius:0 80px 80px 80px;transform:rotate(20deg)}.studio-export{padding:29px}.studio-export .eyebrow{font-size:9px;color:var(--muted);margin-bottom:16px}.studio-export h2{font-size:26px}.studio-export>p:not(.eyebrow){font-size:12px;color:var(--muted);line-height:1.9;margin-top:14px}.studio-export pre{padding:20px;background:var(--soft);border-radius:8px;margin:20px 0;font:12px/1.9 monospace;overflow:auto;color:var(--ink)}.studio-export .button{font-size:12px;width:100%}.studio-export>small{display:block;font-size:10px;color:var(--muted);line-height:1.8;margin-top:15px}.studio-status{min-height:22px;margin:20px 0;font-size:12px;color:var(--muted)}
  @media(max-width:900px){.studio-toolbar{gap:20px}.hue-control{flex-basis:100%}.harmony-control{flex:1}.studio-bottom{grid-template-columns:1fr}.studio-swatch{padding:20px 14px;min-height:230px}.studio-preview{min-height:430px}.preview-composition{right:20px}.studio-export{display:block}}
  @media(max-width:480px){.studio-toolbar{padding:20px 15px}.harmony-control{width:100%;gap:5px}.harmony-control button{flex:1;padding:10px 8px;font-size:10px}.harmony-control small{font-size:8px;line-height:1.5}.studio-toolbar>.button{width:100%}.studio-swatches{grid-template-columns:1fr}.studio-swatch{min-height:93px;padding:18px 22px;flex-direction:row;align-items:center}.swatch-hex{font-size:22px;text-align:right}.swatch-index{font-size:11px}.swatch-circle{top:-60px;width:130px;height:130px;right:10px}.studio-preview{padding:22px;min-height:430px}.preview-copy{padding-top:90px}.preview-copy h2{font-size:34px}.preview-composition{opacity:.4;right:-15px;top:20px}.preview-bottom{font-size:7px;line-height:1.5}.studio-export{padding:23px}}
